const reel = $("reel"), reelBtn = $("reel-btn");
const prefersReducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
const vio = new IntersectionObserver(([en]) => { if (en.isIntersecting) { if (!prefersReducedMotion) reel.play().catch(() => {}); } else reel.pause(); }, { threshold: 0.3 });
vio.observe(reel);
